class Solution:
    def smallestMaxGap(self, stations: List[int], extra: int) -> float:
        gaps = [b - a for a, b in zip(stations, stations[1:])]
        added = [0] * len(gaps)
        for _ in range(extra):
            i = max(range(len(gaps)), key=lambda q: gaps[q] / (added[q] + 1))
            added[i] += 1
        return max(g / (a + 1) for g, a in zip(gaps, added))

