class Solution {
    public double smallestMaxGap(int[] stations, int extra) {
        int m = stations.length - 1;
        int[] added = new int[m];
        for (int t = 0; t < extra; t++) {
            int best = 0;
            for (int i = 1; i < m; i++) {
                double cur = (double) (stations[i + 1] - stations[i]) / (added[i] + 1);
                if (cur > (double) (stations[best + 1] - stations[best]) / (added[best] + 1)) best = i;
            }
            added[best]++;
        }
        double worst = 0;
        for (int i = 0; i < m; i++) worst = Math.max(worst, (double) (stations[i + 1] - stations[i]) / (added[i] + 1));
        return worst;
    }
}

