class Solution {
public:
    double smallestMaxGap(vector<int>& stations, int extra) {
        int m = stations.size() - 1;
        vector<int> added(m, 0);
        auto piece = [&](int i) { return (double) (stations[i + 1] - stations[i]) / (added[i] + 1); };
        for (int t = 0; t < extra; t++) {
            int best = 0;
            for (int i = 1; i < m; i++) if (piece(i) > piece(best)) best = i;
            added[best]++;
        }
        double worst = 0;
        for (int i = 0; i < m; i++) worst = max(worst, piece(i));
        return worst;
    }
};

