            if (cur > (double) (stations[best + 1] - stations[best]) / (added[best] + 1)) best = i;
        }
        added[best]++;
    }
    double worst = 0;
    for (int i = 0; i < m; i++) {
        double cur = (double) (stations[i + 1] - stations[i]) / (added[i] + 1);
        if (cur > worst) worst = cur;
    }
    free(added);
    return worst;
