import math

class Solution:
    def smallestMaxGap(self, stations: List[int], extra: int) -> float:
        gaps = [b - a for a, b in zip(stations, stations[1:])]
        lo, hi = 0.0, float(max(gaps))
        for _ in range(100):
            mid = (lo + hi) / 2
            need = sum(math.ceil(g / mid) - 1 for g in gaps)
            if need <= extra:
                hi = mid
            else:
                lo = mid
        return hi

