class Solution {
    public double smallestMaxGap(int[] stations, int extra) {
        double lo = 0, hi = 0;
        for (int i = 0; i + 1 < stations.length; i++) hi = Math.max(hi, stations[i + 1] - stations[i]);
        for (int it = 0; it < 100; it++) {
            double mid = (lo + hi) / 2;
            long need = 0;
            for (int i = 0; i + 1 < stations.length; i++) need += (long) Math.ceil((stations[i + 1] - stations[i]) / mid) - 1;
            if (need <= extra) hi = mid; else lo = mid;
        }
        return hi;
    }
}

